def digest(text):return hashlib.sha256(text.encode('utf-8')).hexdigest()
def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root',type=Path,default=Path.cwd())
    parser.add_argument('--apply',action='store_true')
    args=parser.parse_args();root=args.root.resolve();changes=[]
    for name,patch in PATCHES.items():
        target=root/name
        if target.is_symlink() or not target.resolve().is_relative_to(root):raise RuntimeError('Unsafe target: '+name)
        raw=target.read_bytes();text=raw.decode('utf-8-sig').replace('\r\n','\n')
        if digest(text)==digest(patch['after']):continue
        if digest(text)!=patch['before']:raise RuntimeError('Source differs from reviewed upload; no writes: '+name)
        revised=patch['after']
        if b'\r\n' in raw:revised=revised.replace('\n','\r\n')
        updated=(b'\xef\xbb\xbf' if raw.startswith(b'\xef\xbb\xbf') else b'')+revised.encode('utf-8')
        changes.append((target,raw,updated))
    if not args.apply:
        print('DRY RUN PASSED. Test files needing alignment: '+str(len(changes)));return
    node=shutil.which('node')
    if not node:raise RuntimeError('Node was not found. No changes made.')
    env=os.environ.copy()
    for key in list(env):
        if key.startswith(('GMAIL_','GOOGLE_','PERPLEXITY_','NMP_')):env.pop(key,None)
    for key in ('ENABLE_GMAIL','ENABLE_GMAIL_SENDING','ENABLE_GMAIL_DRAFT_CREATION','ENABLE_GMAIL_MAILBOX_CHECK','ENABLE_GMAIL_SIGNATURE','ENABLE_PERPLEXITY_RESEARCH','ENABLE_COVER_LETTER_REFINEMENT'):env[key]='false'
    probe=subprocess.run([node,'--input-type=module','-e',"await import('node:sqlite');"],cwd=root,env=env,capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=20)
    if probe.returncode:raise RuntimeError('This test pair requires a Node version with node:sqlite. No changes made.\n'+probe.stderr)
    directory=root/'var/maintenance/backups'/('third-batch-tests-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
    directory.mkdir(parents=True,exist_ok=False)
    for target,raw,updated in changes:
        backup=directory/target.relative_to(root);backup.parent.mkdir(parents=True,exist_ok=True);backup.write_bytes(raw)
    for target,raw,updated in changes:
        if target.read_bytes()!=raw:raise RuntimeError('Concurrent file edit; no writes made.')
    written=[];reports=[]
    try:
        for target,raw,updated in changes:target.write_bytes(updated);written.append((target,raw,updated))
        for name in PATCHES:
            result=subprocess.run([node,'--check',name],cwd=root,env=env,capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=30)
            reports.append(result.stdout+result.stderr)
            if result.returncode:raise RuntimeError('JavaScript syntax check failed: '+name)
        result=subprocess.run([node,'--test','--test-reporter=spec',*PATCHES],cwd=root,env=env,capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=180)
        reports.append(result.stdout+result.stderr)
        report=directory/'targeted-tests.log';report.write_text('\n'.join(reports),encoding='utf-8')
        for line in reports[-1].splitlines():
            if re.match(r'^(?:[✔✖ℹ]|test at |\s+(?:expected:|operator:|error:|code:|at TestContext))',line):print(line)
        print('Test report: '+str(report))
        if result.returncode:raise RuntimeError('Targeted tests failed; original test files will be restored. Keep the report for diagnosis.')
        print('THIRD-BATCH TARGETED TESTS PASSED. Application code unchanged. No Git or production action.')
    except BaseException:
        for target,raw,updated in reversed(written):
            if target.read_bytes()==updated:target.write_bytes(raw)
            else:print('Concurrent edit detected; not overwriting: '+str(target),file=sys.stderr)
        if reports:(directory/'targeted-tests.log').write_text('\n'.join(reports),encoding='utf-8')
        raise
if __name__=='__main__':
    if hasattr(sys.stdout,'reconfigure'):sys.stdout.reconfigure(errors='replace')
    try:main()
    except Exception as error:print('ERROR: '+str(error),file=sys.stderr);sys.exit(1)
